const sample = {
  "demo": true,
  "stripe": [
    {
      "id": "ch_100",
      "amount": 149,
      "currency": "USD"
    },
    {
      "id": "ch_101",
      "amount": 49,
      "currency": "USD"
    },
    {
      "id": "ch_102",
      "amount": 399,
      "currency": "USD"
    }
  ],
  "bank": [
    {
      "id": "txn_900",
      "amount": 149,
      "currency": "USD"
    },
    {
      "id": "txn_901",
      "amount": 49.2,
      "currency": "USD"
    },
    {
      "id": "txn_902",
      "amount": 20,
      "currency": "USD"
    }
  ]
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const leftRows = item.stripe || item.left || [];
const rightRows = item.bank || item.right || [];
const used = new Set();
const matched = [];
const onlyLeft = [];
for (const row of leftRows) {
  const amount = Number(row.amount);
  const hit = rightRows.findIndex((other, index) => !used.has(index) && Math.abs(Number(other.amount) - amount) <= 0.5 && String(other.currency || row.currency || 'USD') === String(row.currency || 'USD'));
  if (hit >= 0) {
    used.add(hit);
    matched.push({ id: row.id, amount, pair: rightRows[hit].id });
  } else {
    onlyLeft.push(row);
  }
}
const onlyRight = rightRows.filter((_, index) => !used.has(index));
const record = {
  matched: matched.length,
  unmatchedLeft: onlyLeft.length,
  unmatchedRight: onlyRight.length,
  onlyLeft,
  onlyRight,
  tolerance: 0.5,
};
const route = onlyLeft.length || onlyRight.length ? 'exceptions' : 'clean';
return {
  summary: matched.length + ' pairs matched. ' + onlyLeft.length + ' stripe and ' + onlyRight.length + ' bank rows still open.',
  route,
  record,
  slackText: route.toUpperCase() + ' reconciliation: ' + matched.length + ' matched, ' + (onlyLeft.length + onlyRight.length) + ' exceptions.',
  actions: [{ app: 'Sheets', operation: 'write exceptions', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'stripe-bank-reconciliation',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
